  pol[k]=value;mayorPolicyLast470A[k]=day;const txt='📜 '+cfg.nm+'：'+(cfg.type==='tax'?(+old).toFixed(1)+'× → '+(+value).toFixed(1)+'×':(value?'開啟':'關閉'))+'｜'+reason;mayorPolicyHistory470A.push({d:day,k,old,value,reason});mayorPolicyHistory470A=mayorPolicyHistory470A.slice(-24);mayorHistory470.push({d:day,m:txt,c:'gold'});mayorHistory470=mayorHistory470.slice(-40);
  if(!window.__noForesight470B&&!mayorPolicyRollback470B)mayorStartPolicyTrial470B(k,old,value,reason,baseline);
  if(k==='schoolLunch')rebuildCov();if(['integratedTransit','freeTransit','completeStreets','parkingManagement'].includes(k)){railOpsDirty463=true;mobility491Dirty=true;}if(k==='recycle')sanDirty445=true;if(k==='ecoReg')markPowerDirty450();if(['waterConserve','reclaimPriority','industrialPretreat','spongeCity'].includes(k))markWaterCycleDirty472();if(['criticalReserve492','emergencyStockpile492'].includes(k)){markResilienceDirty492('policy:'+k);if(k==='criticalReserve492')markPowerDirty471();}mayorSnapshotState470=null;return true;
}

text.polStep:
const polStep=(k,d,nm)=>{
  const next=Math.max(.5,Math.min(2,Math.round((pol[k]+d*.1)*100)/100));
  policyApply504(k,next,{source:'player',reason:'玩家在市政統計面板調整'+nm+'稅'});sTick();showStats();

text.setSvcBudget:
function setSvcBudget(cat,delta){ // T294：調整某類服務預算 ±，即刻 rebuildCov（fill0 全量重建＝增量撤印對稱性保證，見 stampCov 註）
  if(!Object.prototype.hasOwnProperty.call(svcBudget,cat))return svcBudget;
  svcBudget[cat]=clamp(+(svcBudget[cat]+delta).toFixed(2),.5,1.5);
  rebuildCov(); // 用新預算重算所有服務覆蓋半徑
  return svcBudget;
}

